/** Skill label → its full-colour logo slug. Takes priority over SKILL_BRAND. */
const SKILL_MULTICOLOR: Record<string, string> = {
  Firebase: "firebase",
  "Firebase Auth": "firebase",
  "Cloud Messaging": "firebase",
  Analytics: "firebase",
  Crashlytics: "firebase",
  "Android Studio": "androidstudio",
  Xcode: "xcode",
};

type Props = SVGProps<SVGSVGElement> & { name: string };

/** Logo for a skill chip. Prefers a full-colour mark, then a single-colour brand
 * glyph, and falls back to a neutral icon when a skill has no brand (e.g.
 * "RESTful APIs"). */
export function SkillLogo({ name, className, ...props }: Props) {
  const multi = SKILL_MULTICOLOR[name];
  if (multi) {
    const { viewBox, markup } = MULTICOLOR[multi];
    return (
      <svg
        viewBox={viewBox}
        className={className}
        aria-hidden
        dangerouslySetInnerHTML={{ __html: markup }}
        {...props}
      />
    );
  }

  const brand = SKILL_BRAND[name];
  if (!brand) {
    return <Waypoints className={className} aria-hidden />;
  }
  return (
    <svg
      viewBox="0 0 24 24"
      fill={brand.color}
      className={className}
      aria-hidden
      {...props}
    >
      <path d={PATHS[brand.slug]} />
    </svg>
  );
}
